-- The relation table is generated by 0000-00-01 and the activity table by a fixed migration.
-- Config-driven files run on every initialization, so verify the cross-file FK exactly.
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conrelid = 'relation__remote_actor__follow__user'::regclass
      AND conname = 'fk_remote_follow__inbound_follow_activity_row_id'
      AND convalidated
      AND pg_get_constraintdef(oid, true) =
        'FOREIGN KEY (subject_id, object_id, inbound_follow_activity_row_id) REFERENCES activitypub_remote_follow_activities(remote_actor_id, target_user_id, id) DEFERRABLE INITIALLY DEFERRED'
  ) THEN
    RAISE EXCEPTION 'Remote Follow activity FK is missing, unvalidated, or has an unexpected definition';
  END IF;
END $$;
COMMENT ON COLUMN relation__remote_actor__follow__user.inbound_follow_activity_row_id IS 'Current inbound Follow activity cycle; undone identities remain in the activity table and cannot reauthorize this relation.';
